export interface CredentialCreateRequest {
    'label'?: string;
}
/**
 * A glue / \"personal DNS\" record: registers a child nameserver host at the registry as ``<name>.<domain>`` pointing at ``ip`` (and optional ``ip2``). Required before another domain can delegate to that nameserver.
 */
export interface DNSGlue {
    /**
     * only subdomain part
     */
    'name': string;
    'ip': string;
    'ip2'?: string | null;
}
/**
 * A glue / \"personal DNS\" record: registers a child nameserver host at the registry as ``<name>.<domain>`` pointing at ``ip`` (and optional ``ip2``). Required before another domain can delegate to that nameserver.
 */
export interface DNSGlueRequest {
    /**
     * only subdomain part
     */
    'name': string;
    'ip': string;
    'ip2'?: string | null;
}
/**
 * Read-only representation of a DNS record from the cPanel zone dump.
 */
export interface DNSRecord {
    'Line': number;
    'name': string;
    'ttl': number;
    'type': string;
    'address': string;
    'cname': string;
    'exchange': string;
    'preference': number;
    'txtdata': string;
    'unencoded': string;
    'target': string;
    'priority': number;
    'weight': number;
    'port': number;
    'flag': number;
    'tag': string;
    'value': string;
}
/**
 * Validate input for creating or editing a DNS record.
 */
export interface DNSRecordCreateRequest {
    /**
     * Record hostname (use \'@\' or leave empty for zone apex).
     */
    'name': string;
    /**
     * Time to live in seconds.
     */
    'ttl': number;
    /**
     * DNS record type.  * `A` - A * `AAAA` - AAAA * `TYPE257` - TYPE257 * `CNAME` - CNAME * `MX` - MX * `SRV` - SRV * `TXT` - TXT
     */
    'type': DNSRecordCreateTypeEnum;
    /**
     * IPv4/IPv6 address (A/AAAA).
     */
    'address'?: string;
    /**
     * Canonical name (CNAME).
     */
    'cname'?: string;
    /**
     * Mail exchange host (MX).
     */
    'exchange'?: string;
    /**
     * MX preference / priority.
     */
    'preference'?: number;
    /**
     * TXT record data.
     */
    'txtdata'?: string;
    /**
     * Unencoded TXT value.
     */
    'unencoded'?: string;
    /**
     * SRV target host.
     */
    'target'?: string;
    /**
     * SRV priority.
     */
    'priority'?: number;
    /**
     * SRV weight.
     */
    'weight'?: number;
    /**
     * SRV port.
     */
    'port'?: number;
    /**
     * CAA flag (TYPE257).
     */
    'flag'?: number;
    /**
     * CAA tag (TYPE257).
     */
    'tag'?: string;
    /**
     * CAA value (TYPE257).
     */
    'value'?: string;
    /**
     * Line number of existing record to edit. Omit to add a new record.
     */
    'line'?: number;
}


/**
 * * `A` - A * `AAAA` - AAAA * `TYPE257` - TYPE257 * `CNAME` - CNAME * `MX` - MX * `SRV` - SRV * `TXT` - TXT
 */

export const DNSRecordCreateTypeEnum = {
    A: 'A',
    Aaaa: 'AAAA',
    Type257: 'TYPE257',
    Cname: 'CNAME',
    Mx: 'MX',
    Srv: 'SRV',
    Txt: 'TXT',
} as const;

export type DNSRecordCreateTypeEnum = typeof DNSRecordCreateTypeEnum[keyof typeof DNSRecordCreateTypeEnum];


